css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: calc(var(--loader-size) * .82); position: relative; overflow: hidden; border-radius: 6%; background: linear-gradient(#e2e8f0, #94a3b8); box-shadow: inset 0 0 0 2px #64748b; }
.loader::before { content: ''; position: absolute; top: 7%; left: 8%; width: 84%; height: 22%; border-radius: 3px; background: rgba(255, 255, 255, .42); box-shadow: 0 calc(var(--loader-size) * .245) 0 rgba(255, 255, 255, .42); }
.loader .drawer { position: absolute; bottom: 6%; left: 8%; width: 84%; height: 26%; animation: pull-out calc(var(--loader-speed) * 3) ease-in-out infinite; }
.loader .drawer::after { content: ''; position: absolute; z-index: 2; inset: 0; border-radius: 3px; background: linear-gradient(var(--accent), color-mix(in srgb, #000 26%, var(--accent))); box-shadow: inset 0 2px 0 rgba(255, 255, 255, .3); }
.loader .drawer span { position: absolute; bottom: 56%; left: 16%; width: 42%; height: 92%; border-radius: 3px 3px 0 0; background: linear-gradient(var(--accent-2), color-mix(in srgb, #000 18%, var(--accent-2))); animation: file-up calc(var(--loader-speed) * 3) ease-in-out infinite; }
@keyframes pull-out { 0%, 14% { transform: translateX(0); } 44%, 64% { transform: translateX(24%); } 92%, 100% { transform: translateX(0); } }
@keyframes file-up { 0%, 22% { transform: translateY(72%); } 50%, 60% { transform: translateY(-8%); } 88%, 100% { transform: translateY(72%); } }
